INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(76,'AdditionalDetails->POSDetails->AuthLifeCycle->AuthExpirationValue','DE 61_SF12','M','String','1','10','DE 61, subfield 12 (POS Authorization Life Cycle) indicates the number of days a preauthorization will stay in effect for Visa Custom Payment Service automobile rentals and hotel reservations—otherwise it must contain zeros.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(77,'AdditionalDetails->POSDetails->AuthLifeCycle->AuthExpirationUnit','Non ISO Not Used in Master Card','M','String','1','10',' ','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(78,'AdditionalDetails->POSDetails->CountryCode','DE 61_SF13','M','String','1','10','DE 61, subfield 13 (POS Country Code) indicates the country of the POS location (not the acquirer location) using ISO-specified codes.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(79,'AdditionalDetails->POSDetails->PostalCode','DE 61_SF14','M','String','1','10','DE 61, subfield 14 (POS Postal Code) indicates the geographic code of the POS (merchant) location (not the acquirer’s location).','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(80,'AdditionalDetails->CardAcceptorDetails->Address','DE 43','M','String','1','10','DE 43 (Card Acceptor Name/Location) contains the name and location of the card acceptor that defines the point of interaction in both local and interchange environments (excluding ATM and Card-Activated Public Phones).','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(81,'AdditionalDetails->CardAcceptorDetails->Address->Name','DE 43_SF1','M','String','1','10','DE 43, subfield 1 (ATM Owner Name and/or Location, or POS Merchant Name—Payment Facilitator & Sub-Merchant Information) describes either the ATM owning institution name and/or ATM location (that is, the “doing business as” name of the location at which the terminal resides) or the POS Merchant or sub-Merchant Name.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(82,'AdditionalDetails->CardAcceptorDetails->Address->City','DE 43_SF3','M','String','1','10','DE 43, subfield 3 (Card Acceptor City—Sub-Merchant Information) indicates the city of the merchant.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(83,'AdditionalDetails->CardAcceptorDetails->Address->Country','DE 43_SF5','M','String','1','10','DE 43, subfield 5 (Card Acceptor State [U.S.], Province Code [Canada and Canadian territories], or Country Code—Sub-Merchant Information) indicates the ATM or merchant location.','Authorization','TRUE') ON CONFLICT DO NOTHING;
