INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(85,'AdditionalDetails->CardAcceptorDetails->CardAcceptorTerminalId','DE 41','C','String','1','10','DE 41 (Card Acceptor Terminal ID) uniquely identifies a terminal at the card acceptor location of acquiring institutions or merchant POS systems.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(86,'AdditionalDetails->CardAcceptorDetails->CardAcceptorId','DE 42','C','String','1','10','DE 42 (Card Acceptor ID Code) identifies the card acceptor that defines the point of the transaction in both local and interchange environments. DE 42 is used as a merchant ID to uniquely identify the merchant in a POS transaction.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(87,'AdditionalDetails->CardAcceptorDetails->MCC','DE 18','M','String','1','10','DE 18 (Merchant Type) code is the classification of the merchant’s type of business or service.','Authorization','TRUE') ON CONFLICT DO NOTHING;
