INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(91,'AdditionalDetails->NetworkDetails->FinancialNetworkCode','DE 63_SF1','M','String','1','10','DE 63, subfield 1 (Financial Network Code) identifies the specific program or service (for example, the financial network, financial program, or card program) with which the transaction is associated. DE 63 will contain the graduated product when the issuer’s cardholder account participates in the Product Graduation Account Level Management service.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(92,'AdditionalDetails->NetworkDetails->InterchangeRateIndicator','DE 63_SF2','M','String','1','10','DE 63, subfield 2 identifies the transaction as domestic (within the U.S. region) and International (Canada, Asia Pacific, Europe, Latin America/Caribbean and Middle East/Africa), or Intra-country (within a country where an intracurrency transaction agreement is in effect). ','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(93,'AdditionalDetails->NetworkDetails->NetworkReferenceNumber','DE 63_SF3','M','String','1','10','This subfield describes a transaction identification number (switch serial number) generated (or assigned) by the Single Message System.The originating processor (acquirer or issuer) must send the Switch Serial Number from the original response message/0210 in the online exception 04xx message. The Single Message System will provide an Adjustment Switch Serial Number in the online exception 04xx message sent to the receiving processor (acquirer or issuer).','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(94,'AdditionalDetails->NetworkDetails->BanknetReferenceNumber','DE 63_SF4','M','String','1','10','DE 63, subfield 4 contains the Banknet Reference Number.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(95,'AdditionalDetails->NetworkDetails->AcquirerReferenceNumber','DE 63_SF5','M','String','1','10','DE 63, subfield 5 contains the acquirer’s reference number.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(96,'AdditionalDetails->NetworkDetails->GCMSProcessingDateCycleNumber','DE 63_SF6','M','String','1','10','DE 63, subfield 6 contains the Global Clearing Management System (GCMS) processing date and cycle number','Authorization','TRUE') ON CONFLICT DO NOTHING;
