INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(100,'AdditionalDetails->IssuerDetails->AuthorizingAgentInstitutionId','DE 58','C','String','1','10','DE 58 (Authorizing Agent Institution ID) is the institution identifier of the card issuer.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(101,'AdditionalDetails->IssuerDetails->ReceivingInstitutionIdCode','DE 100','C','String','1','10','DE 100 (Receiving Institution ID Code) is the identity of the institution receiving a Request or Advice message in an interchange system if not the same as identified in DE 2 (Primary Account Number [PAN]) or DE 34 (Primary Account Number [PAN], Extended). The Authorization Platform uses DE 100 to determine the destination routing of Administrative/06xx messages. For these messages, DE 33 (Forwarding Institution ID Code) identifies the sender of the message; DE 100 identifies the receiver of the message.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(102,'AdditionalDetails->FeeDetails->CardHolderBillingFee','DE 8','C','String','1','10','DE 8 (Amount, Cardholder Billing Fee) is the fee the issuer is to bill to the cardholder in the same currency as DE 6 (Amount, Cardholder Billing).','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(103,'AdditionalDetails->FeeDetails->TransactionFee','DE 28','C','String','1','10','DE 28 (Amount, Transaction Fee) is the fee charged (for example, by the acquirer) for transaction activity in the currency of DE 4 (Amount, Transaction).','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(104,'AdditionalDetails->FeeDetails->CurrencyConversionFee','','M','String','1','10','','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(105,'AdditionalDetails->ConversionRateDetails->SettlementConversionRate','DE 9','M','String','1','10','DE 9 (Conversion Rate, Settlement) is the factor used in the conversion from transaction to settlement amount. DE 4 (Amount, Transaction) is multiplied by DE 9 to determine DE 5 (Amount, Settlement).','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(106,'AdditionalDetails->ConversionRateDetails->CardHolderBillingConversionRate','DE 10','M','String','1','10','DE 10 (Conversion Rate, Cardholder Billing) is the factor used in the conversion from transaction to cardholder billing amount. DE 4 (Amount, Transaction) is multiplied by DE 10 to determine DE 6 (Amount, Cardholder Billing).','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(107,'AdditionalDetails->ConversionRateDetails->CurrencyConversionAssessmentAmount','','C','String','1','10','','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(108,'AdditionalDetails->PINDetails->CurrencyConversionAssessmentAmount','DE 111','C','String','1','10','DE 111 (Amount, Currency Conversion Assessment) is the amount calculated by the Single Message System that is the result of the currency conversion assessment being applied to qualifying transactions','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(109,'AdditionalDetails->PINDetails->POS_PIN_CaptureCode','DE 26','C','String','1','10','DE 26 (Point of Service [POS] PIN Capture Code) is a code indicating the maximum number of PIN characters that can be accepted by the point of service device used to construct the personal identification number (PIN) data','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(110,'AdditionalDetails->PINDetails->PINData','DE 52','C','String','1','10','DE 52 (Personal ID Number [PIN] Data) contains a number assigned to a cardholder intended to uniquely identify that cardholder at the point of interaction. The use of the PIN is subject to bilateral agreement. The data element may contain the PIN itself or a derivative. This data element transmits PIN information from acquirers to issuers (or to the network) for PIN verification or validation.','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(111,'AdditionalDetails->PINDetails->SecurityRelatedControlInformation','DE 53','C','String','1','10','As of the publication date of this document, the ISO 8583 organization has not determined the specific definition and usage requirements for DE 53 (Security Related Control Information)','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(112,'AdditionalDetails->PINDetails->ICCSystemRelatedData','DE 55','C','String','1','10','DE 55 (Integrated Circuit Card [ICC] System-Related Data) contains chip data formatted in accordance with the Europay Mastercard Visa (EMV) specifications. EMV uses Basic Encoding Rules (BER). (Reference the EMV specifications for further details regarding the coding of BERTLV [ID, Length, Value] data objects.)','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(113,'AdditionalDetails->PINDetails->EnhancedIdentificationData','DE 105','C','String','1','10','DE 105 (Enhanced Identification Data) contains the data required to support the external verification of the Unique Identification Number (UID)','Authorization','TRUE') ON CONFLICT DO NOTHING;
INSERT INTO api_properties_details (sort_order,api_tag_name, iso_data_element,  mandatory_conditional_optional, data_type, min_length, max_length,   description, request_type,active) VALUES(114,'AdditionalDetails->PINDetails->NewPINData','DE 125','C','String','1','10','DE 125 (New PIN Data) for the PIN change function will be passed in DE 125 (New PIN Data), a binary data block containing a derived encrypted value calculated from the new PIN introduced by the cardholder at an ATM offering PIN change. The Single Message System permits PINs from 4 to 12 characters in length. The encrypted PIN block is always 64 bits (8 bytes) in length, regardless of the original PIN length.','Authorization','TRUE') ON CONFLICT DO NOTHING;
